import re
from typing import Dict, Any

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    """Parses an INI file into a dictionary."""

    result: Dict[str, Dict[str, str]] = {}
    current_section: str = None
    current_key: str = None
    current_value: str = None
    state = "scan"  # "scan", "parse", "continue"

    def _interpolate(value: str, section: str) -> str:
        """Recursively interpolates keys."""
        value = value.replace('$', f'${section}:')

        def _interpolate_recursive(val: str) -> str:
            match = re.match(r'([^\s;#"]+|""[^"]*)"', val)
            if match:
                unquoted = match.group(1)
                if unquoted.startswith('"') and unquoted.endswith('"'):
                    return unquoted
                else:
                    return unquoted
            else:
                return val

        return _interpolate_recursive(value)

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue

        if line.startswith(";") or line.startswith("#"):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1]
            if section == "DEFAULT":
                continue
            result[section] = {}
            current_section = section
            state = "parse"
            continue

        if current_section is None:
            raise ValueError("Key line before any section header")

        match = re.match(r"^\s*([a-zA-Z0-9_]+)\s*[=:]\s*(.*)", line)
        if match:
            if current_key is not None:
                raise ValueError("Malformed line: multiple key lines")

            key = match.group(1).lower()
            value = match.group(2).strip()

            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]

            result[current_section][key] = value
            current_key = None
            state = "parse"
            continue

        if state == "parse":
            if current_key is None:
                raise ValueError("Malformed line: value before key")

            if line.startswith(" "):
                value = line.strip()
                if value.startswith('"') and value.endswith('"'):
                    value = value[1:-1]

                if current_value is not None:
                    current_value += "\n" + value
                else:
                    current_value = value
                state = "continue"
                continue

            if current_value is not None:
                result[current_section][current_key] = _interpolate(current_value, current_section)
                current_value = None
                current_key = None
                state = "scan"
                continue
            else:
                raise ValueError("Malformed line: key without value")

    if current_key is not None:
        raise ValueError("Malformed line: key without value")

    return result
