import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = {}
        self.lru_list = []
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def put(self, key, value):
        if key in self.cache:
            self.cache[key] = value
            self.lru_list.remove(key)
            self.lru_list.append(key)
        else:
            if len(self.cache) >= self.capacity:
                self.evict_lru()
            self.cache[key] = value
            self.lru_list.append(key)
        now = self.clock()
        self.cache[key]['expiry'] = now + self.ttl

    def get(self, key, default=None):
        if key in self.cache:
            now = self.clock()
            if now >= self.cache[key]['expiry']:
                self.expirations += 1
                self.lru_list.remove(key)
                del self.cache[key]
                return default
            else:
                self.hits += 1
                self.lru_list.remove(key)
                self.lru_list.append(key)
                return self.cache[key]['value']
        else:
            self.misses += 1
            return default

    def __len__(self):
        count = 0
        for key in self.cache:
            now = self.clock()
            if now < self.cache[key]['expiry']:
                count += 1
        return count

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }

    def evict_lru(self):
        if self.lru_list:
            lru_key = self.lru_list.pop(0)
            del self.cache[lru_key]
            self.evictions += 1
