def summarize_ranges(nums: list[int]) -> str:
    """Sort the numbers and remove duplicates. Then collapse runs of 3 or more consecutive integers into "a..b". Numbers in shorter runs (1 or 2 numbers) are listed individually. Join everything with "," (no spaces). An empty list returns "".

    Examples: [1,2,3,5,7,8] -> "1..3,5,7,8"; [-3,-2,-1,1] -> "-3..-1,1".
    """
    if not nums:
        return ""

    nums = sorted(list(set(nums)))
    result = []

    i = 0
    while i < len(nums):
        if i + 1 < len(nums) and nums[i] + 1 == nums[i + 1]:
            j = i + 1
            while j + 1 < len(nums) and nums[j] + 1 == nums[j + 1]:
                j += 1
            result.append(f"{nums[i]}..{nums[j]}")
            i = j + 1
        else:
            result.append(str(nums[i]))
            i += 1

    return ",".join(result)
